 6.3 Part 1 — Over-Representation Analysis (ORA) What is ORA? ORA asks: “Are my significant DE genes enriched in any pathway more than expected by chance?” It uses a hypergeometric test (equivalent to a one-sided Fisher’s exact test): Query set — significant DE genes (padj &lt; 0.05, |LFC| &gt;= 1), converted to gene symbols, split by direction (up- and down-regulated) Background — all genes tested by DESeq2, converted to gene symbols Gene sets — KEGG pathways FDR correction — empirical FDR (eFDR) via resampling, which accounts for interdependence between gene sets Key assumption: ORA treats all significant genes equally — it ignores magnitude or direction of fold change. Running ORA separately on up- and down-regulated genes partially addresses this, and is why we split the query set below. For a fully ranked approach, see Part 2 (GSEA). 6.3.1 Prepare Input We split significant genes by direction before running ORA. The background remains all genes tested by DESeq2, regardless of direction. sig_up &lt;- res_sig_sym %&gt;% filter(log2FoldChange &gt;= 1) %&gt;% pull(gene) sig_down &lt;- res_sig_sym %&gt;% filter(log2FoldChange &lt;= -1) %&gt;% pull(gene) all_genes &lt;- res_df_sym$gene cat(&quot;Up-regulated genes :&quot;, length(sig_up), &quot;
&quot;) ## Up-regulated genes : 258 cat(&quot;Down-regulated genes :&quot;, length(sig_down), &quot;
&quot;) ## Down-regulated genes : 388 cat(&quot;Background (all tested) :&quot;, length(all_genes), &quot;
&quot;) ## Background (all tested) : 3698 Tip: Always use all tested genes as the background, not the full genome. DESeq2 already filtered to expressed genes, so res_df_sym is the correct pool. Using the full genome inflates the background and produces over-optimistic p-values. 6.3.2 Run ORA ORA is run twice — once for up-regulated genes and once for down-regulated genes — using a helper function to avoid code duplication. set.seed(42) run_ora_mulea &lt;- function(query, background, gmt) { model &lt;- ora( gmt = gmt, element_names = query, background_element_names = background, p_value_adjustment_method = &quot;eFDR&quot;, number_of_permutations = 1000 ) mulea::run_test(model) } ora_up &lt;- run_ora_mulea(sig_up, all_genes, kegg_gmt) ora_down &lt;- run_ora_mulea(sig_down, all_genes, kegg_gmt) cat(&quot;Up — pathways tested:&quot;, nrow(ora_up), &quot;| significant:&quot;, sum(ora_up$eFDR &lt; 0.05, na.rm = TRUE), &quot;
&quot;) ## Up — pathways tested: 121 | significant: 2 cat(&quot;Down — pathways tested:&quot;, nrow(ora_down), &quot;| significant:&quot;, sum(ora_down$eFDR &lt; 0.05, na.rm = TRUE), &quot;
&quot;) ## Down — pathways tested: 121 | significant: 19 6.3.3 Filter and Inspect Significant Pathways ora_up_sig &lt;- ora_up %&gt;% filter(eFDR &lt; 0.05) %&gt;% arrange(eFDR) ora_down_sig &lt;- ora_down %&gt;% filter(eFDR &lt; 0.05) %&gt;% arrange(eFDR) cat(&quot;Significant up pathways :&quot;, nrow(ora_up_sig), &quot;
&quot;) ## Significant up pathways : 2 cat(&quot;Significant down pathways:&quot;, nrow(ora_down_sig), &quot;
&quot;) ## Significant down pathways: 19 Up-regulated genes — enriched pathways DT::datatable( ora_up_sig %&gt;% select(ontology_id, ontology_name, nr_common_with_tested_elements, nr_common_with_background_elements, p_value, eFDR) %&gt;% mutate(across(where(is.numeric), \(x) round(x, 4))), rownames = FALSE, colnames = c(&quot;KEGG ID&quot;, &quot;Pathway&quot;, &quot;Hits in query&quot;, &quot;Hits in background&quot;, &quot;p-value&quot;, &quot;eFDR&quot;), extensions = c(&quot;Buttons&quot;, &quot;Scroller&quot;), options = list(dom = &quot;Bfrtip&quot;, buttons = c(&quot;copy&quot;, &quot;csv&quot;), scrollX = TRUE, scrollY = 300, scroller = TRUE), caption = &quot;Significant ORA pathways — UP-regulated genes (eFDR &lt; 0.05)&quot; ) Down-regulated genes — enriched pathways DT::datatable( ora_down_sig %&gt;% select(ontology_id, ontology_name, nr_common_with_tested_elements, nr_common_with_background_elements, p_value, eFDR) %&gt;% mutate(across(where(is.numeric), \(x) round(x, 4))), rownames = FALSE, colnames = c(&quot;KEGG ID&quot;, &quot;Pathway&quot;, &quot;Hits in query&quot;, &quot;Hits in background&quot;, &quot;p-value&quot;, &quot;eFDR&quot;), extensions = c(&quot;Buttons&quot;, &quot;Scroller&quot;), options = list(dom = &quot;Bfrtip&quot;, buttons = c(&quot;copy&quot;, &quot;csv&quot;), scrollX = TRUE, scrollY = 300, scroller = TRUE), caption = &quot;Significant ORA pathways — DOWN-regulated genes (eFDR &lt; 0.05)&quot; ) 6.3.4 Visualization ora_combined_all &lt;- bind_rows( ora_up_sig %&gt;% mutate(direction = &quot;Up-regulated&quot;), ora_down_sig %&gt;% mutate(direction = &quot;Down-regulated&quot;) ) %&gt;% mutate( eFDR = ifelse(eFDR == 0, 1e-10, eFDR), significance = -log10(eFDR), direction = factor(direction, levels = c(&quot;Up-regulated&quot;, &quot;Down-regulated&quot;)), ontology_name = reorder(paste(ontology_name, direction, sep = &quot;___&quot;), significance) ) ora_barplot_all &lt;- ggplot(ora_combined_all, aes(x = significance, y = ontology_name, fill = direction)) + geom_col(width = 0.7, show.legend = FALSE) + geom_text(aes(label = nr_common_with_tested_elements), hjust = -0.2, size = 3.4, fontface = &quot;bold&quot;) + geom_vline(xintercept = -log10(0.05), linetype = &quot;dashed&quot;, color = &quot;black&quot;, linewidth = 0.5) + facet_grid(direction ~ ., scales = &quot;free_y&quot;, space = &quot;free_y&quot;, switch = &quot;y&quot;) + scale_y_discrete(labels = function(x) sub(&quot;___.*$&quot;, &quot;&quot;, x)) + scale_fill_manual(values = c(&quot;Up-regulated&quot; = &quot;#C1666B&quot;, &quot;Down-regulated&quot; = &quot;#406E8E&quot;)) + scale_x_continuous(expand = expansion(mult = c(0, 0.16))) + theme_bw() + theme( strip.background = element_blank(), strip.placement = &quot;outside&quot;, strip.text.y.left = element_text(angle = 0, face = &quot;bold&quot;, size = 11), panel.grid.major.y = element_blank() ) + labs( title = &quot;ORA — All Significant KEGG Pathways by Direction (eFDR &lt; 0.05)&quot;, subtitle = &quot;Treatment vs Control | E. coli MG1655&quot;, x = &quot;-log10(eFDR)&quot;, y = NULL ) ora_barplot_all suppressMessages(ggplotly(ora_barplot_all)) 6.3.5 Critical Interpretation — Spurious Hits Always ask: does this pathway make biological sense for your organism? Two pathways in our results deserve scrutiny: Pinene, camphor and geraniol degradation (eco00907) — a plant terpenoid pathway. It appears here because KEGG annotates a handful of E. coli enzymes with broad substrate specificity to this pathway. The perfect overlap (6 hits in query, 6 in background, eFDR = 0) is a red flag: a tiny gene set where every background gene is DE will always score as maximally significant, regardless of biological relevance. Caprolactam degradation (eco00930) — same issue: only 3 genes in the background, all 3 in the query. Perfect overlap in a tiny set is statistically inevitable, not biologically meaningful. Thinking strategy: 1. Check the gene set size — very small sets (&lt; 5 genes) are prone to spurious enrichment 2. Check the overlap — 100% overlap is suspicious, not impressive 3. Ask whether the pathway is plausible for your organism and condition 4. Cross-reference with GSEA — if it does not appear there, treat it with scepticism Spurious hits are removed from both directional result tables before visualisation. clean_ora &lt;- function(ora_results, direction_label) { ora_results %&gt;% filter(!grepl(&quot;Pine|camphor|Caprolactam&quot;, ontology_name, ignore.case = TRUE)) %&gt;% mutate(direction = direction_label) } ora_up_clean &lt;- clean_ora(ora_up_sig, &quot;Up-regulated&quot;) ora_down_clean &lt;- clean_ora(ora_down_sig, &quot;Down-regulated&quot;) cat(&quot;Up pathways after cleaning :&quot;, nrow(ora_up_clean), &quot;
&quot;) ## Up pathways after cleaning : 2 cat(&quot;Down pathways after cleaning:&quot;, nrow(ora_down_clean), &quot;
&quot;) ## Down pathways after cleaning: 17 Visualise ORA Results 6.3.6 Faceted Bar Plot — Enriched Pathways by Direction Up- and down-regulated results are shown in separate facets, each ordered independently by significance. The gene count (number of DE genes hitting each pathway) is printed at the end of each bar. ora_combined &lt;- bind_rows( ora_up_clean %&gt;% slice_head(n = 6), ora_down_clean %&gt;% slice_head(n = 6) ) %&gt;% mutate( eFDR = ifelse(eFDR == 0, 1e-10, eFDR), significance = -log10(eFDR), direction = factor(direction, levels = c(&quot;Up-regulated&quot;, &quot;Down-regulated&quot;)), ontology_name = reorder(paste(ontology_name, direction, sep = &quot;___&quot;), significance) ) ora_barplot &lt;- ggplot(ora_combined, aes(x = significance, y = ontology_name, fill = direction)) + geom_col(width = 0.7, show.legend = FALSE) + geom_text(aes(label = nr_common_with_tested_elements), hjust = -0.2, size = 3.4, fontface = &quot;bold&quot;) + geom_vline(xintercept = -log10(0.05), linetype = &quot;dashed&quot;, color = &quot;black&quot;, linewidth = 0.5) + facet_grid(direction ~ ., scales = &quot;free_y&quot;, space = &quot;free_y&quot;, switch = &quot;y&quot;) + scale_y_discrete(labels = function(x) sub(&quot;___.*$&quot;, &quot;&quot;, x)) + scale_fill_manual(values = c(&quot;Up-regulated&quot; = &quot;#C1666B&quot;, &quot;Down-regulated&quot; = &quot;#406E8E&quot;)) + scale_x_continuous(expand = expansion(mult = c(0, 0.16))) + theme_bw() + theme( strip.background = element_blank(), strip.placement = &quot;outside&quot;, strip.text.y.left = element_text(angle = 0, face = &quot;bold&quot;, size = 11), panel.grid.major.y = element_blank() ) + labs( title = &quot;ORA — Enriched KEGG Pathways by Direction (eFDR &lt; 0.05)&quot;, subtitle = &quot;Treatment vs Control | E. coli MG1655&quot;, x = &quot;-log10(eFDR)&quot;, y = NULL ) ora_barplot suppressMessages(ggplotly(ora_barplot)) 6.3.7 Lollipop Plot — Gene Hits per Pathway Point colour encodes eFDR; position on