 6.4 Part 2 — Gene Set Enrichment Analysis (GSEA) What is GSEA? GSEA asks: “Are genes in a pathway coordinately shifting up or down across my full ranked list?” Unlike ORA, GSEA: Uses all tested genes — capturing coordinated but subtle pathway-level changes Ranks genes by a metric encoding both significance and direction Returns a Normalised Enrichment Score (NES): positive NES = pathway upregulated in treatment; negative NES = pathway downregulated Why signed log p-value for ranking? rank = sign(LFC) x -log10(pvalue) Genes at the top are significantly upregulated; genes at the bottom are significantly downregulated. This is more robust than ranking on LFC alone, which can place noisy high-fold-change genes from lowly expressed genes at the extremes. 📘 Note: Genes with pvalue = 0 (below machine precision in DESeq2) are excluded because -log10(0) = Inf is not a valid ranking score. These are the most extremely significant genes and their exclusion has minimal impact on pathway-level results. 6.4.1 Prepare the Ranked Gene List ranked_df &lt;- res_df_sym %&gt;% filter(!is.na(pvalue), !is.na(log2FoldChange)) %&gt;% filter(pvalue &gt; 0) %&gt;% # exclude p=0 -&gt; log10(0) = Inf mutate(rank_metric = sign(log2FoldChange) * -log10(pvalue)) %&gt;% arrange(desc(rank_metric)) %&gt;% distinct(gene, .keep_all = TRUE) rank_vector &lt;- ranked_df$rank_metric names(rank_vector) &lt;- ranked_df$gene cat(&quot;Genes in ranked list :&quot;, length(rank_vector), &quot;
&quot;) ## Genes in ranked list : 3697 cat(&quot;Infinite values :&quot;, sum(!is.finite(rank_vector)), &quot;
&quot;) ## Infinite values : 0 cat(&quot;Top 5 (upregulated) :&quot;, paste(head(names(rank_vector), 5), collapse = &quot;, &quot;), &quot;
&quot;) ## Top 5 (upregulated) : b3508, b3510, gadC, b3509, gadB cat(&quot;Bottom 5 (downreg.) :&quot;, paste(tail(names(rank_vector), 5), collapse = &quot;, &quot;), &quot;
&quot;) ## Bottom 5 (downreg.) : mglB, garL, b3127, b0553, garR 6.4.2 Convert GMT to fgsea Format fgsea requires a named list of gene vectors — one entry per pathway. pathways_list &lt;- setNames( kegg_gmt$list_of_values, kegg_gmt$ontology_name ) cat(&quot;Pathways in list:&quot;, length(pathways_list), &quot;
&quot;) ## Pathways in list: 121 cat(&quot;Example entry :&quot;, pathways_list[[1]][1:5], &quot;
&quot;) ## Example entry : aceE aceF lpd yahK frmA 6.4.3 Run GSEA set.seed(42) gsea_results &lt;- fgsea( pathways = pathways_list, stats = rank_vector, minSize = 10, maxSize = 500, nPermSimple = 10000 ) cat(&quot;Pathways tested :&quot;, nrow(gsea_results), &quot;
&quot;) ## Pathways tested : 77 cat(&quot;Significant (padj &lt; 0.05):&quot;, sum(gsea_results$padj &lt; 0.05, na.rm = TRUE), &quot;
&quot;) ## Significant (padj &lt; 0.05): 2 cat(&quot;Nominal (pval &lt; 0.05) :&quot;, sum(gsea_results$pval &lt; 0.05, na.rm = TRUE), &quot;
&quot;) ## Nominal (pval &lt; 0.05) : 18 6.4.4 Filter and Inspect Significant Pathways gsea_sig &lt;- gsea_results %&gt;% as.data.frame() %&gt;% filter(padj &lt; 0.05) %&gt;% arrange(padj) cat(&quot;Significant GSEA pathways:&quot;, nrow(gsea_sig), &quot;
&quot;) ## Significant GSEA pathways: 2 cat(&quot; Activated (NES &gt; 0) :&quot;, sum(gsea_sig$NES &gt; 0), &quot;
&quot;) ## Activated (NES &gt; 0) : 0 cat(&quot; Suppressed (NES &lt; 0) :&quot;, sum(gsea_sig$NES &lt; 0), &quot;
&quot;) ## Suppressed (NES &lt; 0) : 2 DT::datatable( gsea_sig %&gt;% select(pathway, NES, pval, padj, size) %&gt;% mutate( direction = ifelse(NES &gt; 0, &quot;Activated&quot;, &quot;Suppressed&quot;), across(where(is.numeric), \(x) round(x, 4)) ) %&gt;% arrange(desc(abs(NES))), rownames = FALSE, colnames = c(&quot;Pathway&quot;, &quot;NES&quot;, &quot;p-value&quot;, &quot;padj&quot;, &quot;Size&quot;, &quot;Direction&quot;), extensions = c(&quot;Buttons&quot;, &quot;Scroller&quot;), options = list( dom = &quot;Bfrtip&quot;, buttons = c(&quot;copy&quot;, &quot;csv&quot;), scrollX = TRUE, scrollY = 300, scroller = TRUE ), caption = &quot;Significant GSEA pathways — treatment vs control (padj &lt; 0.05)&quot; ) Visualise GSEA Results 6.4.5 NES Bar Plot — Activated and Suppressed Pathways cols_direction &lt;- c(&quot;Activated&quot; = &quot;#d7191c&quot;, &quot;Suppressed&quot; = &quot;#2c7bb6&quot;) # Use top 20 by |NES| if more than 20 significant, otherwise show all gsea_bar &lt;- gsea_results %&gt;% as.data.frame() %&gt;% filter(pval &lt; 0.05) %&gt;% slice_max(abs(NES), n = 20) %&gt;% mutate( direction = ifelse(NES &gt; 0, &quot;Activated&quot;, &quot;Suppressed&quot;), pathway = fct_reorder(pathway, NES) ) gsea_nesplot &lt;- ggplot(gsea_bar, aes(x = NES, y = pathway, fill = direction)) + geom_col(width = 0.7, alpha = 0.9) + geom_vline(xintercept = 0, color = &quot;black&quot;, linewidth = 0.5) + geom_vline(xintercept = c(-1, 1), linetype = &quot;dashed&quot;, color = &quot;grey50&quot;, linewidth = 0.4) + scale_fill_manual(values = cols_direction) + theme_bw() + theme(legend.position = &quot;bottom&quot;) + labs( title = &quot;GSEA — Normalised Enrichment Scores (pval &lt; 0.05)&quot;, subtitle = &quot;Treatment vs Control | E. coli MG1655&quot;, x = &quot;Normalised Enrichment Score (NES)&quot;, y = NULL, fill = NULL ) gsea_nesplot ggplotly(gsea_nesplot) 6.4.6 Dot Plot — NES, padj and Gene Set Size gsea_dotplot &lt;- ggplot(gsea_bar, aes(x = NES, y = pathway, size = size, color = padj)) + geom_point(alpha = 0.85) + geom_vline(xintercept = 0, linetype = &quot;dashed&quot;, color = &quot;grey50&quot;) + scale_color_gradient(low = &quot;#CA0020&quot;, high = &quot;#92C5DE&quot;, name = &quot;padj&quot;) + scale_size_continuous(name = &quot;Genes in set&quot;, range = c(3, 10)) + theme_bw() + theme(legend.position = &quot;right&quot;) + labs( title = &quot;GSEA — Pathway Dot Plot&quot;, subtitle = &quot;Point size = genes in set | Colour = padj&quot;, x = &quot;NES&quot;, y = NULL ) gsea_dotplot ggplotly(gsea_dotplot) 6.4.7 Enrichment Plot — Top Pathways The enrichment plot shows the running sum of the enrichment score for a single pathway across the ranked gene list. The peak of the curve is the enrichment score. Genes from the pathway are shown as vertical bars (the “rug”) at the bottom. # Top activated pathway top_up &lt;- gsea_results %&gt;% as.data.frame() %&gt;% filter(NES &gt; 0) %&gt;% slice_min(pval, n = 1) %&gt;% pull(pathway) # Top suppressed pathway top_down &lt;- gsea_results %&gt;% as.data.frame() %&gt;% filter(NES &lt; 0) %&gt;% slice_min(pval, n = 1) %&gt;% pull(pathway) if (length(top_up) &gt; 0) { plotEnrichment(pathways_list[[top_up]], rank_vector) + labs(title = paste(&quot;Top activated:&quot;, top_up)) } if (length(top_down) &gt; 0) { plotEnrichment(pathways_list[[top_down]], rank_vector) + labs(title = paste(&quot;Top suppressed:&quot;, top_down)) }

